struct Fuzz {
extension SyntaxText {
  fileprivate func containsPlaceholderEnd() -> Bool {
    guard self.count >= 2 else {
      return false
    }

    for idx in 0..<(self.count - 1) {
      let c = self[idx]
      guard c != "\n" else {
        return false
      }

      if self[idx] == "#", self[idx + 1] == ">" {
        return true
      }
    }
    return false
  }
}
}

